require __DIR__ . '/../app/bootstrap.php'; require_login(); require_once __DIR__ . '/../app/recurring_charges.php'; $user=current_user(); if($_SERVER['REQUEST_METHOD']!=='POST')sync_recurring_charges($pdo);
$tenant=(int)($_GET['inquilino_id']??0);$location=(int)($_GET['ubicacion_id']??0);$year=(int)($_GET['anio']??date('Y'));$from=$_GET['desde']??'';$to=$_GET['hasta']??'';
$locations=$pdo->query("SELECT id,nombre FROM ubicaciones ORDER BY nombre")->fetchAll();
$tenants=$pdo->query("SELECT t.id,t.nombre,l.nombre ubicacion_nombre,u.nombre unidad_nombre FROM inquilinos t LEFT JOIN unidades u ON u.id=t.unidad_id LEFT JOIN ubicaciones l ON l.id=u.ubicacion_id ORDER BY l.nombre,u.nombre,t.nombre")->fetchAll();
$makeWhere=function(string $x,string $t,string $u,bool $dates=true)use($tenant,$location,$year,$from,$to):array{$parts=[];$args=[];if($tenant){$parts[]="$t.id=?";$args[]=$tenant;}if($location){$parts[]="$u.ubicacion_id=?";$args[]=$location;}if($dates&&$year>0){$parts[]="YEAR($x.fecha)=?";$args[]=$year;}if($dates&&$from!==''){$parts[]="$x.fecha>=?";$args[]=$from;}if($dates&&$to!==''){$parts[]="$x.fecha<=?";$args[]=$to;}return [$parts?' WHERE '.implode(' AND ',$parts):'',$args];};
$makeIncomeWhere=function(string $t,string $u,bool $dates=true)use($tenant,$location,$year,$from,$to):array{$parts=[];$args=[];$period="COALESCE(x.periodo_alquiler,DATE_FORMAT(x.fecha,'%Y-%m'))";if($tenant){$parts[]="$t.id=?";$args[]=$tenant;}if($location){$parts[]="$u.ubicacion_id=?";$args[]=$location;}if($dates&&$year>0){$parts[]="LEFT($period,4)=?";$args[]=(string)$year;}if($dates&&$from!==''){$parts[]="$period>=?";$args[]=substr($from,0,7);}if($dates&&$to!==''){$parts[]="$period<=?";$args[]=substr($to,0,7);}return [$parts?' WHERE '.implode(' AND ',$parts):'',$args];};
$sums=function(string $table)use($pdo,$makeWhere):array{[$w,$a]=$makeWhere('x','t','u');$q=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) total,COUNT(*) n FROM $table x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id$w");$q->execute($a);return $q->fetch();};
$c=$sums('cargos');[$paidWhere,$paidArgs]=$makeWhere('x','t','u');$paidStmt=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) total FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id".($paidWhere?' AND '.substr($paidWhere,7):'').($paidWhere?' AND ':' WHERE ')."x.estado_pago='PAGADO'");$paidStmt->execute($paidArgs);$paid=(float)$paidStmt->fetchColumn();[$pendingWhere,$pendingArgs]=$makeWhere('x','t','u');$pendingStmt=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) total FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id".($pendingWhere?' AND '.substr($pendingWhere,7):'').($pendingWhere?' AND ':' WHERE ')."x.estado_pago='PENDIENTE'");$pendingStmt->execute($pendingArgs);$pending=(float)$pendingStmt->fetchColumn();[$incomeWhere,$incomeArgs]=$makeIncomeWhere('t','u');$incomeStmt=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) total,COUNT(*) n FROM ingresos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id$incomeWhere");$incomeStmt->execute($incomeArgs);$i=$incomeStmt->fetch();$balance=(float)$i['total']-$paid;$forecast=$balance-$pending;$rent=((float)$paid+$pending)>0?(float)$paid/((float)$paid+$pending)*100:0;
[$cw,$ca]=$makeWhere('x','t','u');$types=$pdo->prepare("SELECT x.tipo,COUNT(*) n,SUM(x.importe) total FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id$cw GROUP BY x.tipo ORDER BY total DESC");$types->execute($ca);$types=$types->fetchAll();
[$iw,$ia]=$makeIncomeWhere('t','u');$methods=$pdo->prepare("SELECT x.metodo,COUNT(*) n,SUM(x.importe) total FROM ingresos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id$iw GROUP BY x.metodo ORDER BY total DESC");$methods->execute($ia);$methods=$methods->fetchAll();
[$tw,$ta]=$makeWhere('t','t','u',false);$tenantSql="SELECT t.id,t.nombre,l.nombre ubicacion_nombre,u.nombre unidad_nombre FROM inquilinos t LEFT JOIN unidades u ON u.id=t.unidad_id LEFT JOIN ubicaciones l ON l.id=u.ubicacion_id$tw";$tenantStmt=$pdo->prepare($tenantSql);$tenantStmt->execute($ta);$byTenant=[];
foreach($tenantStmt->fetchAll() as $tr){$dateParts=[];$dateArgs=[];if($year>0){$dateParts[]='YEAR(fecha)=?';$dateArgs[]=$year;}if($from!==''){$dateParts[]='fecha>=?';$dateArgs[]=$from;}if($to!==''){$dateParts[]='fecha<=?';$dateArgs[]=$to;}$dateSql=$dateParts?' AND '.implode(' AND ',$dateParts):'';$q=$pdo->prepare('SELECT COALESCE(SUM(importe),0) FROM cargos WHERE inquilino_id=?'.$dateSql);$q->execute(array_merge([(int)$tr['id']],$dateArgs));$charges=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(importe),0) FROM cargos WHERE inquilino_id=? AND estado_pago='PAGADO'".$dateSql);$q->execute(array_merge([(int)$tr['id']],$dateArgs));$paidCharges=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(importe),0) FROM cargos WHERE inquilino_id=? AND estado_pago='PENDIENTE'".$dateSql);$q->execute(array_merge([(int)$tr['id']],$dateArgs));$pendingCharges=(float)$q->fetchColumn();$incomeParts=['inquilino_id=?'];$incomeArgs=[(int)$tr['id']];$periodExpr="COALESCE(periodo_alquiler,DATE_FORMAT(fecha,'%Y-%m'))";if($year>0){$incomeParts[]="LEFT($periodExpr,4)=?";$incomeArgs[]=(string)$year;}if($from!==''){$incomeParts[]="$periodExpr>=?";$incomeArgs[]=substr($from,0,7);}if($to!==''){$incomeParts[]="$periodExpr<=?";$incomeArgs[]=substr($to,0,7);}$iq=$pdo->prepare('SELECT COALESCE(SUM(importe),0) FROM ingresos WHERE '.implode(' AND ',$incomeParts));$iq->execute($incomeArgs);$income=(float)$iq->fetchColumn();$tr['cargos']=$charges;$tr['pagados']=$paidCharges;$tr['pendientes']=$pendingCharges;$tr['ingresos']=$income;$tr['balance']=$income-$paidCharges;$tr['previsto']=$income-$paidCharges-$pendingCharges;$byTenant[]=$tr;}
usort($byTenant,fn($a,$b)=>$a['balance']<=>$b['balance']);
[$mcw,$mca]=$makeWhere('x','t','u',false);$monthly=[];
for($offset=23;$offset>=0;$offset--){$month=date('Y-m',strtotime(date('Y-m-01')." -$offset months"));$start=$month.'-01';$end=date('Y-m-t',strtotime($start));$monthArgs=[];$filterTenant='';if($tenant){$filterTenant.=' AND t.id=?';$monthArgs[]=$tenant;}if($location){$filterTenant.=' AND u.ubicacion_id=?';$monthArgs[]=$location;}$q=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id WHERE x.fecha BETWEEN ? AND ?$filterTenant");$q->execute(array_merge([$start,$end],$monthArgs));$ch=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id WHERE x.fecha BETWEEN ? AND ? AND x.estado_pago='PAGADO'$filterTenant");$q->execute(array_merge([$start,$end],$monthArgs));$chPaid=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id WHERE x.fecha BETWEEN ? AND ? AND x.estado_pago='PENDIENTE'$filterTenant");$q->execute(array_merge([$start,$end],$monthArgs));$chPending=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(x.importe),0) FROM ingresos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id WHERE COALESCE(x.periodo_alquiler,DATE_FORMAT(x.fecha,'%Y-%m'))=?$filterTenant");$q->execute(array_merge([$month],$monthArgs));$in=(float)$q->fetchColumn();$monthly[]=['mes'=>$month,'cargos'=>$ch,'pagados'=>$chPaid,'pendientes'=>$chPending,'ingresos'=>$in];}
[$aw,$aa]=$makeWhere('x','t','u');$annualSql="SELECT YEAR(x.fecha) anio,COALESCE(SUM(CASE WHEN x.tipo='Alquiler' THEN x.importe ELSE 0 END),0) alquiler,COALESCE(SUM(x.importe),0) cargos,COALESCE(SUM(CASE WHEN x.estado_pago='PAGADO' THEN x.importe ELSE 0 END),0) pagados,COALESCE(SUM(CASE WHEN x.estado_pago='PENDIENTE' THEN x.importe ELSE 0 END),0) pendientes FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id$aw GROUP BY YEAR(x.fecha)";$annualC=$pdo->prepare($annualSql);$annualC->execute($aa);$annualC=$annualC->fetchAll();[$aiw,$aia]=$makeIncomeWhere('t','u');$incomeYearExpr="LEFT(COALESCE(x.periodo_alquiler,DATE_FORMAT(x.fecha,'%Y-%m')),4)";$annualSqlI="SELECT $incomeYearExpr anio,COALESCE(SUM(x.importe),0) ingresos FROM ingresos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id$aiw GROUP BY $incomeYearExpr";$annualI=$pdo->prepare($annualSqlI);$annualI->execute($aia);$annualI=$annualI->fetchAll();$annualMap=[];foreach($annualC as $r){$y=(int)$r['anio'];$annualMap[$y]=['anio'=>$y,'alquiler'=>(float)$r['alquiler'],'cargos'=>(float)$r['cargos'],'pagados'=>(float)$r['pagados'],'pendientes'=>(float)$r['pendientes'],'ingresos'=>0.0];}foreach($annualI as $r){$y=(int)$r['anio'];if(!isset($annualMap[$y]))$annualMap[$y]=['anio'=>$y,'alquiler'=>0.0,'cargos'=>0.0,'pagados'=>0.0,'pendientes'=>0.0,'ingresos'=>0.0];$annualMap[$y]['ingresos']=(float)$r['ingresos'];}foreach($annualMap as &$r){$r['balance']=$r['ingresos']-$r['pagados'];$r['previsto']=$r['balance']-$r['pendientes'];}unset($r);$annual=array_values($annualMap);usort($annual,fn($a,$b)=>$b['anio']<=>$a['anio']);
$taxParts=[];$taxArgs=[];if($tenant){$taxParts[]='t.id=?';$taxArgs[]=$tenant;}if($location){$taxParts[]='u.ubicacion_id=?';$taxArgs[]=$location;}$taxWhere=$taxParts?' WHERE '.implode(' AND ',$taxParts):'';
$taxSql="SELECT YEAR(x.fecha) anio,x.tipo,COUNT(*) movimientos,COALESCE(SUM(x.importe),0) total,COALESCE(SUM(CASE WHEN x.pagado_por='Propietario' THEN x.importe ELSE 0 END),0) propietario FROM cargos x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id$taxWhere GROUP BY YEAR(x.fecha),x.tipo ORDER BY anio DESC,x.tipo";$taxStmt=$pdo->prepare($taxSql);$taxStmt->execute($taxArgs);$taxRows=$taxStmt->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(app_setting('titulo_web','APP Alquileres · Gestión de propiedades'))?> · Estadísticas</title><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="assets/app.css"><style>:root{--blue:<?=e(app_setting('color_principal','#2859a6'))?>}</style></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-icon">⌂</span><span>APP Alquileres<small>Estadísticas globales e individuales</small></span></a><a class="btn outline" href="index.php">Volver al inicio</a></header><div class="layout"><nav class="sidebar" aria-label="Menú principal">
<button class="mobile-menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-nav-links" onclick="const n=this.parentElement;const o=n.classList.toggle('mobile-menu-open');this.setAttribute('aria-expanded',String(o));this.querySelector('.toggle-label').textContent=o?'Cerrar menú':'Menú principal';this.querySelector('.toggle-icon').textContent=o?'✕':'☰'"><span class="toggle-label">Menú principal</span><span class="toggle-icon" aria-hidden="true">☰</span></button><div class="mobile-nav-links" id="mobile-nav-links"><div class="nav-heading">MENÚ PRINCIPAL</div><a class="nav-item " href="index.php?page=dashboard"><span class="nav-icon" aria-hidden="true">🏠</span><span>Dashboard</span></a><div class="nav-divider"><span>ALQUILERES</span></div><a class="nav-item " href="ubicaciones.php"><span class="nav-icon" aria-hidden="true">🏢</span><span>Ubicaciones e inmuebles</span></a><a class="nav-item" href="index.php?page=inquilinos"><span class="nav-icon" aria-hidden="true">👥</span><span>Inquilinos</span></a><a class="nav-item" href="recurrentes.php"><span class="nav-icon" aria-hidden="true">🔁</span><span>Cargos recurrentes</span></a><div class="nav-divider"><span>ECONOMÍA</span></div><a class="nav-item" href="index.php?page=cargos"><span class="nav-icon" aria-hidden="true">📋</span><span>Cargos</span></a><a class="nav-item" href="index.php?page=ingresos"><span class="nav-icon" aria-hidden="true">💶</span><span>Ingresos</span></a><a class="nav-item" href="index.php?page=fianzas"><span class="nav-icon" aria-hidden="true">🔐</span><span>Fianzas</span></a><div class="nav-divider"><span>HERRAMIENTAS</span></div><a class="nav-item active" href="estadisticas.php"><span class="nav-icon" aria-hidden="true">📊</span><span>Estadísticas</span></a><?php if($user['rol']==='ADMIN'):?><a class="nav-item" href="index.php?page=usuarios"><span class="nav-icon" aria-hidden="true">⚙️</span><span>Usuarios</span></a><a class="nav-item " href="backup.php"><span class="nav-icon" aria-hidden="true">💾</span><span>Copias de seguridad</span></a><?php endif;?><div class="nav-spacer"></div><?php if($user['rol']==='ADMIN'):?><a class="nav-item" href="configuracion.php"><span class="nav-icon" aria-hidden="true">🛠️</span><span>Configuración</span></a><?php endif;?><a class="nav-item nav-help" href="ayuda.php"><span class="nav-icon" aria-hidden="true">❔</span><span>Ayuda y manual</span></a></div></nav><main class="content"><div class="page-head"><div><h1>Estadísticas</h1><p class="muted">Consulta todas las propiedades o filtra por ubicación, unidad/inquilino, año y fechas.</p></div></div><section class="panel"><form class="form-grid" method="get"><div><label>Ubicación</label><select name="ubicacion_id"><option value="0">Todas las ubicaciones</option><?php foreach($locations as $l):?><option value="<?=$l['id']?>" <?=$location===(int)$l['id']?'selected':''?>><?=e($l['nombre'])?></option><?php endforeach;?></select></div><div><label>Inquilino</label><select name="inquilino_id"><option value="0">Todos los inquilinos</option><?php foreach($tenants as $t):?><option value="<?=$t['id']?>" <?=$tenant===(int)$t['id']?'selected':''?>><?=e($t['nombre'].' · '.$t['ubicacion_nombre'].' / '.$t['unidad_nombre'])?></option><?php endforeach;?></select></div><div><label>Año (0 = todos)</label><input type="number" name="anio" value="<?=$year?>"></div><div><label>Desde</label><input type="date" name="desde" value="<?=e($from)?>"></div><div><label>Hasta</label><input type="date" name="hasta" value="<?=e($to)?>"></div><div class="full"><button class="btn primary">Aplicar filtros</button></div></form></section><div class="kpis"><div class="kpi"><span>Ingresos cobrados</span><strong class="green"><?=money($i['total'])?></strong></div><div class="kpi"><span>Cargos pagados</span><strong><?=money($paid)?></strong></div><div class="kpi"><span>Balance real</span><strong style="color:<?=$balance<0?'#c33434':'#13804a'?>"><?=money($balance)?></strong></div><div class="kpi"><span>Pendiente de pago</span><strong><?=money($pending)?></strong></div><div class="kpi"><span>Balance previsto</span><strong style="color:<?=$forecast<0?'#c33434':'#13804a'?>"><?=money($forecast)?></strong></div><div class="kpi"><span>Cargos pagados</span><strong><?=number_format($rent,1,',','.')?>% del total</strong></div></div><section class="panel"><h3>Cargos por tipo</h3><div class="table-wrap"><table><tr><th>Tipo</th><th>Movimientos</th><th>Total</th><th>Porcentaje</th></tr><?php foreach($types as $r):?><tr><td><?=e($r['tipo'])?></td><td><?=$r['n']?></td><td><?=money($r['total'])?></td><td><?=number_format((float)$c['total']?(float)$r['total']/(float)$c['total']*100:0,1,',','.')?>%</td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Ingresos por método</h3><div class="table-wrap"><table><tr><th>Método</th><th>Movimientos</th><th>Total</th></tr><?php foreach($methods as $r):?><tr><td><?=e($r['metodo'])?></td><td><?=$r['n']?></td><td><?=money($r['total'])?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Balance por inquilino</h3><div class="table-wrap"><table><tr><th>Ubicación</th><th>Unidad</th><th>Inquilino</th><th>Ingresos</th><th>Cargos pagados</th><th>Pendientes</th><th>Balance real</th><th>Previsto</th><th>PDF</th></tr><?php foreach($byTenant as $r):?><tr><td><?=e($r['ubicacion_nombre'])?></td><td><?=e($r['unidad_nombre'])?></td><td><?=e($r['nombre'])?></td><td><?=money($r['ingresos'])?></td><td><?=money($r['pagados'])?></td><td><?=money($r['pendientes'])?></td><td style="color:<?=$r['balance']<0?'#c33434':'#13804a'?>"><?=money($r['balance'])?></td><td style="color:<?=$r['previsto']<0?'#c33434':'#13804a'?>"><?=money($r['previsto'])?></td><td><a href="pdf_inquilino.php?id=<?=$r['id']?>">Ver PDF</a></td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Evolución mensual (últimos 24 meses)</h3><div class="table-wrap"><table><tr><th>Mes</th><th>Ingresos</th><th>Cargos pagados</th><th>Pendientes</th><th>Balance real</th><th>Balance previsto</th></tr><?php foreach($monthly as $r):?><tr><td><?=e($r['mes'])?></td><td><?=money($r['ingresos'])?></td><td><?=money($r['pagados'])?></td><td><?=money($r['pendientes'])?></td><td><?=money($r['ingresos']-$r['pagados'])?></td><td><?=money($r['ingresos']-$r['pagados']-$r['pendientes'])?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h3>Detalle anual por tipo de gasto</h3><p class="muted">Este resumen incluye todos los años y respeta los filtros de ubicación e inquilino. El importe del propietario identifica los cargos registrados como pagados por el propietario; revisa facturas y requisitos fiscales antes de declarar.</p><div class="table-wrap"><table><tr><th>Año</th><th>Tipo de cargo</th><th>Movimientos</th><th>Importe total</th><th>Pagado por propietario</th></tr><?php foreach($taxRows as $r):?><tr><td><?=$r['anio']?></td><td><?=e($r['tipo'])?></td><td><?=$r['movimientos']?></td><td><?=money($r['total'])?></td><td><?=money($r['propietario'])?></td></tr><?php endforeach;?><?php if(!$taxRows):?><tr><td colspan="5">No hay cargos registrados para los filtros seleccionados.</td></tr><?php endif;?></table></div></section><section class="panel"><h3>Resumen anual</h3><div class="table-wrap"><table><tr><th>Año</th><th>Cargos alquiler</th><th>Total cargos</th><th>Pagados</th><th>Pendientes</th><th>Ingresos</th><th>Balance real</th><th>Previsto</th></tr><?php foreach($annual as $r):?><tr><td><?=$r['anio']?></td><td><?=money($r['alquiler'])?></td><td><?=money($r['cargos'])?></td><td><?=money($r['pagados'])?></td><td><?=money($r['pendientes'])?></td><td><?=money($r['ingresos'])?></td><td><?=money($r['balance'])?></td><td><?=money($r['previsto'])?></td></tr><?php endforeach;?></table></div></section></main></div><script>document.addEventListener('DOMContentLoaded',()=>{const nav=document.querySelector('.sidebar');if(!nav)return;const btn=nav.querySelector('.mobile-menu-toggle');const links=nav.querySelector('.mobile-nav-links');if(!btn||!links)return;links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{if(window.matchMedia('(max-width:650px)').matches){nav.classList.remove('mobile-menu-open');btn.setAttribute('aria-expanded','false');btn.querySelector('.toggle-label').textContent='Menú principal';btn.querySelector('.toggle-icon').textContent='☰';}}));});</script></body></html>